'use strict';

const assert=require('node:assert/strict');

/** @typedef {{goodDirections:number,oneDirections:number}} Profile */
/** @typedef {{triangularSources:number,allChoicesComplete:number,
 *   permutationFailures:number,negativeControls:number,
 *   negativeRefusals:number,triangularScalarFunctions:number,
 *   distinctScalarTruthFunctions:number,rootCandidates:number,
 *   nonzeroSubspaces:number,allSubspaceChecks:number,
 *   subspaceFailures:number}} CensusReport */

/**
 * Four-bit source state is generated by four arbitrary lower-prefix Boolean
 * gate truth tables. Their lengths are 1, 2, 4, 8 bits, totalling 15.
 * This enumerates all 2^15 compatible triangular 4-bit permutations.
 * Independently of any previously implemented matrix/flag attacker.
 *
 * @param {number} gateBits
 * @returns {Uint8Array}
 */
function triangularPermutation(gateBits) {
  const gates=[
    gateBits&1,(gateBits>>>1)&3,(gateBits>>>3)&15,(gateBits>>>7)&255
  ];
  const result=new Uint8Array(16);
  for(let x=0;x<16;x++) {
    let y=x;
    for(let j=0;j<4;j++) {
      if((gates[j]>>>(x&((1<<j)-1)))&1)y^=1<<j;
    }
    result[x]=y;
  }
  return result;
}

/**
 * A scalar Boolean truth vector uses bit x for its value at input x.
 * @param {Uint8Array} permutation
 * @param {number} outputMask
 * @returns {number}
 */
function scalarTruth(permutation,outputMask) {
  let truth=0;
  for(let x=0;x<16;x++) {
    let bits=permutation[x]&outputMask;
    bits^=bits>>>2;
    bits^=bits>>>1;
    truth|=(bits&1)<<x;
  }
  return truth;
}

/**
 * For each direction h in GF(2)^4, decide whether its first scalar
 * derivative is *globally* constant over all 16 x.
 * goodDirections has bit h set iff the derivative is constant.
 * oneDirections has bit h set iff that constant is one.
 *
 * @param {number} truth
 * @param {Map<number,Profile>} cache
 * @returns {Profile}
 */
function derivativeProfile(truth,cache) {
  const known=cache.get(truth);
  if(known!==undefined)return known;
  let goodDirections=0,oneDirections=0;
  for(let h=0;h<16;h++) {
    const expected=((truth>>>0)&1)^((truth>>>h)&1);
    let globallyConstant=true;
    for(let x=1;x<16;x++) {
      const observed=((truth>>>x)&1)^((truth>>>(x^h))&1);
      if(observed!==expected){globallyConstant=false;break;}
    }
    if(!globallyConstant)continue;
    goodDirections|=1<<h;
    if(expected)oneDirections|=1<<h;
  }
  const profile={goodDirections,oneDirections};
  cache.set(truth,profile);
  return profile;
}

/** @param {number} mask @returns {number} */
function weight(mask) {
  let total=0;
  for(let h=0;h<16;h++)if(mask&(1<<h))total++;
  return total;
}

/**
 * For a given exact four-bit permutation, ask the stronger question:
 * does EVERY globally legitimate nonzero derivative scalar choice admit
 * a completion all the way to the zero input subspace?
 *
 * A subspace is represented as a bitset of its 16 input directions. The
 * null-derivative kernel for a global scalar is computed by set intersection.
 * All possible valid scalar choices at every reachable stage are traversed.
 *
 * @param {Profile[]} profiles scalar output masks indexed 0..15
 * @returns {{allChoicesComplete:boolean,rootCandidates:number}}
 */
function allGlobalChoicesComplete(profiles) {
  /** @type {Map<number,boolean>} */
  const memo=new Map();

  /** @param {number} subspace @returns {boolean} */
  function complete(subspace) {
    if(subspace===1)return true;
    const cached=memo.get(subspace);
    if(cached!==undefined)return cached;

    let valid=0;
    for(let mask=1;mask<16;mask++) {
      const p=profiles[mask];
      if((subspace&~p.goodDirections)!==0)continue;
      if((subspace&p.oneDirections)===0)continue;
      valid++;
      const next=(subspace&~p.oneDirections)&0xffff;
      assert.equal(weight(next)*2,weight(subspace),
        'Kernel of an exact nonzero linear form must halve the subspace');
      if(!complete(next)) {
        memo.set(subspace,false);
        return false;
      }
    }
    const result=valid>0;
    memo.set(subspace,result);
    return result;
  }

  let rootCandidates=0;
  for(let mask=1;mask<16;mask++) {
    const p=profiles[mask];
    if(p.goodDirections===0xffff && p.oneDirections!==0)rootCandidates++;
  }
  return {allChoicesComplete:complete(0xffff),rootCandidates};
}

/**
 * Synthetic output permutation unrelated to the compatible triangular
 * family, used as a nonvacuous negative oracle census control.
 * @param {number} seed
 * @returns {Uint8Array}
 */
function shuffledPermutation(seed) {
  let state=seed>>>0;
  /** @returns {number} */
  function next() {
    state^=state<<13;
    state^=state>>>17;
    state^=state<<5;
    return state>>>0;
  }
  const result=Uint8Array.from({length:16},(_,i)=>i);
  for(let i=15;i>0;i--) {
    const j=next()%(i+1);
    const old=result[i];
    result[i]=result[j];
    result[j]=old;
  }
  return result;
}

/**
 * Exhaust every linear subspace of GF(2)^4, independently of any output
 * mask choices. The 67 returned membership bitsets include the zero space
 * and full four-dimensional space. A nonzero h extends U to U ∪ (U+h).
 * @returns {number[]}
 */
function enumerateInputSubspaces() {
  const all=[1];
  const known=new Set(all);
  for(let index=0;index<all.length;index++) {
    const U=all[index];
    for(let h=1;h<16;h++) {
      if(U&(1<<h))continue;
      let extended=U;
      for(let x=0;x<16;x++) {
        if(U&(1<<x))extended|=1<<(x^h);
      }
      if(known.has(extended))continue;
      known.add(extended);
      all.push(extended);
    }
  }
  return all;
}

/**
 * Enumerate all 32768 4-bit T-function permutations and every globally
 * legitimate greedy scalar mask at every stage. No sampling or hidden
 * source-private flag construction is involved.
 *
 * @returns {CensusReport}
 */
function runCensus() {
  /** @type {Map<number,Profile>} */
  const profilesCache=new Map();
  const subspaces=enumerateInputSubspaces();
  assert.equal(subspaces.length,67,'Four-bit space has exactly 67 linear subspaces');
  let triangularSources=0,allChoicesComplete=0,permutationFailures=0;
  let rootCandidates=0,subspaceFailures=0,allSubspaceChecks=0;
  for(let source=0;source<(1<<15);source++) {
    const permutation=triangularPermutation(source);
    if(new Set(permutation).size!==16)permutationFailures++;
    /** @type {Profile[]} */
    const profiles=Array.from({length:16},(_,w)=>
      derivativeProfile(scalarTruth(permutation,w),profilesCache));
    const result=allGlobalChoicesComplete(profiles);
    for(const U of subspaces) {
      if(U===1)continue;
      allSubspaceChecks++;
      const exists=profiles.some((p,w)=>w>0&&
        (U&~p.goodDirections)===0&&(U&p.oneDirections)!==0);
      if(!exists)subspaceFailures++;
    }
    triangularSources++;
    if(result.allChoicesComplete)allChoicesComplete++;
    rootCandidates+=result.rootCandidates;
  }
  const triangularScalarFunctions=profilesCache.size;
  let negativeRefusals=0;
  const negativeControls=64;
  for(let seed=1;seed<=negativeControls;seed++) {
    const permutation=shuffledPermutation(Math.imul(seed,0x9e3779b9));
    assert.equal(new Set(permutation).size,16);
    const profiles=Array.from({length:16},(_,w)=>
      derivativeProfile(scalarTruth(permutation,w),profilesCache));
    const result=allGlobalChoicesComplete(profiles);
    if(!result.allChoicesComplete)negativeRefusals++;
  }
  return {
    triangularSources,allChoicesComplete,permutationFailures,
    negativeControls,negativeRefusals,
    triangularScalarFunctions,distinctScalarTruthFunctions:profilesCache.size,
    rootCandidates,nonzeroSubspaces:subspaces.length-1,
    allSubspaceChecks,subspaceFailures
  };
}

if(require.main===module) {
  process.stdout.write('EXACT_GREEDY_FLAG_CENSUS '+JSON.stringify(runCensus())+'\n');
}
module.exports={runCensus,triangularPermutation,allGlobalChoicesComplete};
